// Route Update — детерминированная маршрутизация кодом. AI в решениях не участвует.
const upd = $('Telegram Trigger').first().json || {};
const m = upd.message || {};
const from = m.from || {};
const telegram_id = from.id != null ? String(from.id) : '';
const chat_id = m.chat && m.chat.id != null ? String(m.chat.id) : telegram_id;
const update_id = String(upd.update_id == null ? '' : upd.update_id);
const text = typeof m.text === 'string' ? m.text.trim() : '';
function rows(name, key) { return $(name).all().map(function (i) { return i.json; }).filter(function (r) { return r && r[key]; }); }
const S = {};
rows('Get Bot Settings', 'setting_key').forEach(function (r) { S[r.setting_key] = r.setting_value; });
function parseIds(v) {
  try { const a = JSON.parse(v || '[]'); if (Array.isArray(a)) return a.map(function (x) { return String(x).trim(); }).filter(Boolean); } catch (e) {}
  return String(v || '').split(/[\s,;]+/).map(function (s) { return s.trim(); }).filter(Boolean);
}
const isAdmin = telegram_id !== '' && parseIds(S.admin_telegram_ids).indexOf(telegram_id) >= 0;
const tz = S.timezone || 'Asia/Almaty';
const now = DateTime.now().setZone(tz);
const employee = rows('Get Employee', 'employee_id').find(function (r) { return String(r.employee_status || '').toUpperCase() === 'ACTIVE'; });
const session = rows('Get Registration Session', 'telegram_id')[0] || null;
const dialog = rows('Get Dialog State', 'telegram_id')[0] || null;
let dialogExpired = false;
if (dialog) { const e = DateTime.fromISO(String(dialog.expires_at || '')); dialogExpired = !e.isValid || e < now; }
const isForwarded = !!(m.forward_origin || m.forward_date || m.forward_from || m.forward_from_chat || m.forward_sender_name);
const base = { telegram_id: telegram_id, chat_id: chat_id, update_id: update_id, text: text, is_admin: isAdmin, registered: !!employee, has_session: !!session, dialog_flow: dialog ? dialog.flow : '', dialog_expired: dialogExpired };

function out(target, extra) { return [{ json: Object.assign({ target: target }, base, extra || {}) }]; }
function direct(t, kb) { return out('DIRECT', { reply: { action: 'REPLY', chat_id: chat_id, text: t, keyboard_type: kb || 'main_menu', keyboard: [] } }); }
function shift(action) {
  return out('SHIFT', { shift: { action: action, telegram_id: telegram_id, chat_id: chat_id, update_id: update_id, location_json: m.location ? JSON.stringify(m.location) : '', message_date: Number(m.date) || 0, is_forwarded: isForwarded } });
}
function hr(action, payload) {
  return out('HR', { hr: { action: action, telegram_id: telegram_id, chat_id: chat_id, text: text, update_id: update_id, payload_json: payload ? JSON.stringify(payload) : '' } });
}
function ai(q) { return out('AI', { ai_text: q }); }

if (!telegram_id) return out('NONE');

// Психолог — сохранённый сценарий
if (text === '🧠 Психолог' || text === '/psychologist' || /психолог|psycholog/i.test(text)) {
  return direct('🧠 Психологическая поддержка\n\nЕсли тебе тяжело, тревожно или просто хочется поговорить — напиши нашему боту-психологу:\n\n👉 @neploxo_HQ_bot\nhttps://t.me/neploxo_HQ_bot\n\nТвоя переписка с ним не попадает в HR-бот.', employee ? 'main_menu' : 'remove');
}

// 1. Нет активного профиля (включая незавершённую регистрацию) → Registration
if (!employee || session) {
  return out('REGISTRATION', { reg: {
    telegram_id: telegram_id, chat_id: chat_id, text: text,
    contact_json: m.contact ? JSON.stringify(m.contact) : '',
    update_id: update_id, first_name: String(from.first_name || ''), username: String(from.username || ''),
  } });
}

// 2. Геолокация → Shift Engine (он проверяет запрос, свежесть, пересылку, live location и радиус)
if (m.location) return shift('LOCATION');

const SHIFT_FLOWS = ['CHECK_IN', 'CHECK_OUT'];
const HR_FLOWS = ['VACATION', 'SICK', 'MEETING', 'ADMIN_CONFIRM'];
if (text === '❌ Отмена' || text === '/cancel' || text === 'Отмена') {
  if (dialog && SHIFT_FLOWS.indexOf(dialog.flow) >= 0) return shift('CANCEL');
  if (dialog && HR_FLOWS.indexOf(dialog.flow) >= 0) return hr('DIALOG_INPUT');
  return direct('Действие отменено. Выберите пункт меню.');
}

const MENU_ACTIONS = {
  '🟢 Начать работу': ['SHIFT', 'REQUEST_CHECK_IN'],
  '🔴 Завершить работу': ['SHIFT', 'REQUEST_CHECK_OUT'],
  '🐟 Fish Coins': ['HR', 'MY_COINS'],
  '🐟 Мои Fish Coins': ['HR', 'MY_COINS'],
  '📊 Моя статистика': ['HR', 'MY_STATS'],
  '👤 Мой профиль': ['HR', 'MY_PROFILE'],
  '🏖 Отпуск': ['HR', 'START_VACATION'],
  '🏖️ Отпуск': ['HR', 'START_VACATION'],
  '🤒 Больничный': ['HR', 'START_SICK'],
  '🏥 Больничный': ['HR', 'START_SICK'],
  '📅 Встреча': ['HR', 'START_MEETING'],
};
const ADMIN_TEXTS = ['⚙️ Админ-панель', '📋 Заявки на рассмотрении', '👥 Сотрудники'];
const ADMIN_CMD = /^\/(admin|pending|employees|approve|reject|coins|achieve|geo|reset)(\s|$|@)/i;

// Админ — только по списку admin_telegram_ids (не по должности)
if (ADMIN_TEXTS.indexOf(text) >= 0 || ADMIN_CMD.test(text)) {
  if (!isAdmin) return out('DIRECT', { result: 'FORBIDDEN', reply: { action: 'REPLY', chat_id: chat_id, text: '⛔ Доступ запрещён. Админ-панель доступна только назначенным администраторам.', keyboard_type: 'main_menu', keyboard: [] } });
  return hr(text === '⚙️ Админ-панель' ? 'ADMIN_MENU' : 'ADMIN_COMMAND');
}
if (text === '✅ Да, выполнить' || text === '❌ Нет, отменить') {
  if (dialog && dialog.flow === 'ADMIN_CONFIRM') return hr(text === '✅ Да, выполнить' ? 'CONFIRM_YES' : 'CONFIRM_NO');
  return direct('Нет действия, ожидающего подтверждения.');
}
if (MENU_ACTIONS[text]) {
  const a = MENU_ACTIONS[text];
  return a[0] === 'SHIFT' ? shift(a[1]) : hr(a[1]);
}
if (text === '/start' || text === '/menu' || text === '🏠 Главное меню') {
  return direct('Здравствуйте, ' + String(employee.full_name || from.first_name || '') + '! Ваш ID: ' + employee.tuna_id + '.\nВыберите действие в меню ниже.');
}
if (text === '❓ Помощь' || text === '/help') {
  return direct('ℹ️ TUNA HR бот\n🟢 Начать работу / 🔴 Завершить работу — отметка по геолокации (радиус ' + (S.work_radius_m || 150) + ' м).\n🐟 Fish Coins — баланс и история.\n📊 Моя статистика — смены и часы за месяц.\n🏖 Отпуск, 🤒 Больничный, 📅 Встреча — заявки HR.\n👤 Мой профиль — ваши данные.\n🤖 Спросить TUNA — вопросы ассистенту.\n🧠 Психолог — /psychologist');
}
if (text === 'ℹ️ Что такое Fish Coins') {
  return direct('🐟 Fish Coins — внутренние баллы TUNA: +1 при регистрации (один раз), +1 за каждую завершённую смену с геопроверкой (не более одной в день), а также за достижения по правилам администратора. Максимум ' + (S.max_fish_coins || 100) + '.');
}
if (text === '🤖 Спросить TUNA') {
  return ai('Пользователь нажал кнопку «🤖 Спросить TUNA». Коротко поприветствуй по-русски и по-казахски и предложи задать вопрос.');
}
// 3. Активный диалог → его владельцу
if (dialog && !dialogExpired && HR_FLOWS.indexOf(dialog.flow) >= 0 && text) return hr('DIALOG_INPUT');
if (dialog && !dialogExpired && SHIFT_FLOWS.indexOf(dialog.flow) >= 0) {
  return out('DIRECT', { reply: { action: 'REPLY', chat_id: chat_id, text: '📍 Жду вашу геолокацию: нажмите «📍 Отправить геолокацию» ниже или «❌ Отмена».', keyboard_type: 'location', keyboard: [] } });
}
if (m.contact) return direct('Номер телефона уже подтверждён при регистрации. Выберите действие в меню.');
if (!text) return direct('Я понимаю текст, кнопки меню и геолокацию. Выберите действие в меню ниже.');
// 4. Остальное → AI-ассистент (только объясняет)
return ai(text.slice(0, 1500));

const route = $('Route Update').first().json;
const r = $input.first().json || {};
if (r.action === 'NOOP') return [{ json: { send_mode: 'none' } }];
let text = typeof r.text === 'string' ? r.text : '';
let kbType = r.keyboard_type || 'main_menu';
if (!text) { text = '⚠️ Техническая ошибка, ваши данные не потеряны. Повторите действие чуть позже. Код: ' + $execution.id; kbType = route.registered ? 'main_menu' : 'remove'; }
function esc(s) { return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
// HR & Admin уже экранирует HTML; остальные источники экранируем здесь.
if (route.target !== 'HR') text = esc(text);
let mode = 'remove';
let kb = [];
if (kbType === 'main_menu') mode = route.is_admin ? 'menu_admin' : 'menu';
else if (kbType === 'location') mode = 'location';
else if (kbType === 'contact') mode = 'contact';
else if (kbType === 'reply') {
  kb = (Array.isArray(r.keyboard) ? r.keyboard : []).filter(function (row) { return Array.isArray(row) && row.length; }).map(function (row) { return row.map(function (t) { return String(t).slice(0, 60); }); });
  const shape = kb.map(function (row) { return row.length; }).join('_');
  const SUPPORTED = ['1', '1_1', '2_1', '3_2', '2_2_2_1'];
  if (SUPPORTED.indexOf(shape) >= 0) mode = 'kb_' + shape;
  else if (kb.length) {
    // Нестандартная клавиатура: варианты текстом, ответ можно ввести вручную.
    text += '\n\nВарианты: ' + kb.map(function (row) { return row.map(esc).join(' | '); }).join(' | ');
    kb = [];
  }
}
if (text.length > 4000) text = text.slice(0, 4000) + '…';
return [{ json: { send_mode: mode, chat_id: String(r.chat_id || route.chat_id), text: text, kb: kb } }];

options.systemMessage:
Ты — TUNA, дружелюбный HR-ассистент компании в Telegram. Часовой пояс компании — Asia/Almaty.

Язык: отвечай на языке пользователя — по-русски или по-казахски (қазақ тілінде). Если язык неясен — по-русски.

Твоя роль — ТОЛЬКО разговор: объяснять, как пользоваться ботом, и направлять к нужной кнопке меню.
Кнопки: 🟢 Начать работу, 🔴 Завершить работу (отметка по свежей геолокации в радиусе рабочей точки), 🐟 Fish Coins (баланс), 📊 Моя статистика, 🏖 Отпуск, 🤒 Больничный, 📅 Встреча (заявки HR), 👤 Мой профиль, 🤖 Спросить TUNA. Психологическая поддержка — бот @neploxo_HQ_bot.

Fish Coins: +1 при регистрации (один раз), +1 за завершённую смену при успешной геопроверке на входе и выходе (не более одной в день), достижения — только по правилам администратора, максимум 100.

Строго запрещено (у тебя нет инструментов для этого, и нельзя делать вид, что ты это сделал):
- изменять баланс Fish Coins, начислять или списывать монеты;
- изменять время прихода/ухода, создавать или закрывать смены;
- выдавать права администратора;
- показывать данные других сотрудников (у тебя их нет);
- одобрять или отклонять отпуск, больничный, встречи;
- выполнять код или команды.
На такие просьбы вежливо откажи и подскажи нужную кнопку или обращение к администратору.
Никогда не придумывай баланс, статистику или статусы заявок — направляй к кнопкам 🐟 Fish Coins / 📊 Моя статистика.
По больничному никогда не спрашивай диагноз.
Отвечай кратко (до 600 символов), без HTML и Markdown.

